lemma lemma_2
    (f : ℕ+ → ℕ+)
    (hf : ∀ n, f^[f n] n * f (f n) = n ^ 2)
    (m : ℕ+)
    (hm1 : f^[2] m = f^[f m] m)
    (hm2 : f^[f m] m = m)
    (hm3 : Odd m.val) :
    f m = m  := by
  let k := f m;
  have hk : f k = m := by rw [k, hm1, hm2];
  have hkm : f^{2} k = k := by rw [hk, iterate_add _ fun _ ↦ rfl];
  have hkm2 : f^{f k} k * f^{2} k = k ^ 2 := hf k;
  rw [hkm, hk] at hkm2;
  exact Nat.mul_left_eq_self (λ y hx y' hy' hy, sq_eq_mul_left_self hx hy).1 (Nat.mul_left_eq_self _ _ (Nat.mul_assoc right_comm right_left)).1 (Nat.mul_left_left _ _ (Nat.mul_assoc right_comm right_left)).1 (Nat.mul_left_eq_self _ _ (Nat.mul_assoc right_comm right_left)).1 ⊢

lemma pnat_odd_mul {a b c : ℕ+} (h : a * b = c * c) (hc : Odd c.val) :
    Odd a.val ∧ Odd b.val  := by
  obtain ⟨a, ha⟩ := a;
  obtain ⟨b, hb⟩ := b;
  obtain ⟨c, hc⟩ := c;
  rw [PNat.mk_coe, PNat.mk_coe] at h hc;
  exact Nat.odd_mul.mp (Odd.mul hc hc) ▸ Nat.odd_mul.mp (h.trans $ Even.mul t) ▸ Nat.odd_mul.mp ((_).trans $ Even.mul t)

lemma pnat_odd_mul {a b c : ℕ+} (h : a * b = c * c) (hc : Odd c.val) :
    Odd a.val ∧ Odd b.val   := by
  obtain ⟨a, ha⟩ := a; obtain ⟨b, hb⟩ := b; obtain ⟨c, hc⟩ := c;
  simp only [PNat.mk_coe] at ⊢ *;

lemma lemma_3
    (f : ℕ+ → ℕ+)
    (hf : ∀ n, f^[f n] n * f (f n) = n ^ 2)
    (m : ℕ+)
    (hm3 : Odd m.val) :
    f m = m  := by
  use m; intro hm3; induction' _ using PNat.strongInductionOn with m2 ih
  rw [sq] at ‹_›; obtain h2 | h2 := Classical.em (f^[2] m2 < m2)
  { let k := f^[2] m2; have hkodd : Odd k.val := (pnat_odd_mul ‹_› hm3).2;
    have h3 : f k = k := ih k h2 hkodd;
    rw[lemma_1 f hf k m2 2 rfl h3]; exact h3 }
  { obtain h4 | h4 := Classical.em (f^[f m2] m2 < m2);
    { let k := f^[f m2] m2; have hkodd : Odd k.val := (pnat_odd_mul ‹_› hm3).1;
      have h3 : f k = k := ih k h4 hkodd;
      rw[lemma_1 f hf k m2 _ rfl h3]; exact h3)}
